#include <cmath>
#include <vector>
#include <cstdio>
#include <algorithm>

// Cox-Ross-Rubinstein binomial pricer. Self-contained, C++17.
struct CrrOption {
    double S, K, r, sigma, T;   // spot, strike, cont. rate, vol, maturity
    bool   isCall = true;
    bool   american = false;

    double price(int N) const {
        const double dt   = T / N;
        const double u    = std::exp(sigma * std::sqrt(dt));
        const double d    = 1.0 / u;
        const double disc = std::exp(-r * dt);
        const double p    = (std::exp(r * dt) - d) / (u - d);   // risk-neutral up-prob

        std::vector<double> V(N + 1);
        for (int j = 0; j <= N; ++j) {                  // j = number of down moves
            const double ST = S * std::pow(u, N - j) * std::pow(d, j);
            V[j] = isCall ? std::max(ST - K, 0.0) : std::max(K - ST, 0.0);
        }
        for (int i = N - 1; i >= 0; --i) {              // sweep back through the tree
            for (int j = 0; j <= i; ++j) {
                V[j] = disc * (p * V[j] + (1.0 - p) * V[j + 1]);
                if (american) {
                    const double Sj = S * std::pow(u, i - j) * std::pow(d, j);
                    V[j] = std::max(V[j], isCall ? Sj - K : K - Sj);
                }
            }
        }
        return V[0];
    }
};

int main() {
    const CrrOption call{100.0, 105.0, 0.05, 0.25, 1.0, true, false};
    const CrrOption amerPut{100.0, 105.0, 0.05, 0.25, 1.0, false, true};
    for (int N : {10, 50, 100, 500})
        std::printf("N=%3d  euroCall=%.6f  amerPut=%.6f\n", N, call.price(N), amerPut.price(N));
    return 0;
}
